\begin{tabular}{lrrrr}
\toprule
& \multicolumn{2}{c}{\textbf{@55K}} & \multicolumn{2}{c}{\textbf{@112K}} \\
\cmidrule(lr){2-3} \cmidrule(lr){4-5}
Loss component & Share & (\%) & Share & (\%) \\
\midrule
Reward head & --- & 49.0 & --- & 38.1 \\
